// -----------------------------------------------------
// 標準の日常スクリプト
// -----------------------------------------------------

@StartSkit,全キャラ初期設定
// コンディションの初期化（時間指定）
@SetSkitCondition,,12:00:00,Fine

// コンディションの初期化（オート）
@SetSkitCondition,auto,auto,Fine
// @SetSkitCondition,auto,auto,Fine
// @SetSkitCondition,04-01,auto,Rain
// @SetSkitCondition,auto,12:00:00,Fine

// カメラ位置の初期化
@SetSkitCamera,GL_R014_001,2,-1,0.6

// 非登場キャストの非表示
@HideSkitCast,主人公
@HideSkitCast,彩葉
@HideSkitCast,紬
@HideSkitCast,凪
@HideSkitCast,花音
@HideSkitCast,スカーレット
@HideSkitCast,エステファニア
@HideSkitCast,ひまり子
@HideSkitCast,ロイズ
@HideSkitCast,配膳ロボ
@EndSkit


@StartSkit,全キャラ初期位置設定
// キャスト位置の初期化
@SetSkitCast,主人公,GL_R002_000,0,0,0,0
@SetSkitCast,ひまり子,GL_R009_000,0,0,0,0
@SetSkitCast,紬,GL_R004_000,0,0,0,0
@SetSkitCast,花音,GL_R007_000,0,0,0,0
@SetSkitCast,凪,GL_R005_000,0,0,0,0
@SetSkitCast,スカーレット,GL_R014_001,1.5,-1,45,0
@SetSkitCast,エステファニア,GL_R008_000,0,0,0,0
@SetSkitCast,彩葉,GL_R014_001,3,-1,-90,0
@SetSkitCast,ロイズ,GL_R010_001,0,0,0,0
@SetSkitCast,配膳ロボ,GL_R014_001,1,1.4,-40,0
@EndSkit


@StartSkit,初期アクション設定
@PlaySkitCastAction,スカーレット,Action0
@PlaySkitCastAction,彩葉,Action0
@ShowSkitCastMessage,スカーレット
今天也要吃到撑
吃饭去啦——desu！
@EndSkit

@PlaySkit,全キャラ初期設定
@PlaySkit,全キャラ初期位置設定
@SetAfterSkit,初期アクション設定
